SELECT 
    ROUND(
        (
            COUNT(*) WHERE Name = 'Student' AND Year(Date) = 2010
        ) /
        (
            COUNT(*) WHERE Name = 'Student' AND Year(Date) = 2010
        ) * 100
    ) AS percentage_difference_2010,
    ROUND(
        (
            COUNT(*) WHERE Name = 'Student' AND Year(Date) = 2011
        ) /
        (
            COUNT(*) WHERE Name = 'Student' AND Year(Date) = 2011
        ) * 100
    ) AS percentage_difference_2011
FROM badges
WHERE Name = 'Student'

